 static void Tick(){if(!EditorApplication.isPlaying||EditorApplication.isCompiling||++ticks<25)return;p=UnityEngine.Object.FindObjectOfType<NakiPrototype>();if(p==null||Get("world")==null)return;try{if(stage==0){p.enabled=false;Tests();new GameObject("Replay QA HUD").AddComponent<CapitalHudProxy>().target=p;Time.timeScale=0;stage=1;ticks=0;return;}if(stage==1){ScreenCapture.CaptureScreenshot(Out+"replay-menu.png");stage=2;ticks=0;return;}Check(errors.Count==0,"No Unity runtime errors");File.WriteAllText(Out+"smoke-result.txt","PASS "+checks+" native checks\n");End(0);}catch(Exception e){Debug.LogException(e);File.WriteAllText(Out+"smoke-result.txt","FAIL after "+checks+"\n"+e+"\n"+string.Join("\n",errors));End(1);}}
